#include <chrono>
#include <format>
#include <sstream>
#include <string>
#include <cassert>
#include <iostream>

int main() {
    using namespace std::chrono;
    month_day date{March / 15};
    assert(date.ok());
    std::ostringstream text;
    text << date;
    assert(!text.str().empty());
    auto formatted = std::format("{}", date);
    assert(!formatted.empty());
    std::cout << "Checks passed\n";
}
